  /// Zulu
  zulu('Zulu', FixedTimespanSet(FixedTimespan('UTC', offsetSeconds: 0), []));

  factory fromJson(String json) {
    final tz = nameToTz[json];
    if (tz == null) {
      throw ArgumentError.value(json, 'json', 'Unknown time zone ID');
    }
    return tz;
  }

